package com.bankpli.javabank.batch;import com.bankpli.javabank.audit.AuditService;import java.math.BigDecimal;import java.util.*;import java.util.concurrent.atomic.AtomicLong;import org.springframework.stereotype.Service;
@Service public class BatchService {private final AuditService audit;private final AtomicLong sequence=new AtomicLong();public BatchService(AuditService a){audit=a;}public record Transaction(String id,BigDecimal amount,String type){}public record Summary(int count,BigDecimal total,List<Transaction>transactions){}public Summary generate(int count){if(count<1||count>10000)throw new IllegalArgumentException("Count must be between 1 and 10000");List<Transaction>rows=new ArrayList<>();BigDecimal total=BigDecimal.ZERO;for(int i=0;i<count;i++){BigDecimal amount=new BigDecimal("100.00").add(new BigDecimal("25.00").multiply(BigDecimal.valueOf(i)));rows.add(new Transaction("TXN"+sequence.incrementAndGet(),amount,"DEBIT"));total=total.add(amount);}audit.append("BATCH_GENERATED","count="+count+" total="+total);return new Summary(count,total,rows);}public Summary traverse(List<Transaction>transactions){if(transactions.size()>1000)throw new IllegalArgumentException("Chain traversal limit exceeded");BigDecimal total=transactions.stream().map(Transaction::amount).reduce(BigDecimal.ZERO,BigDecimal::add);return new Summary(transactions.size(),total,List.copyOf(transactions));}}
